#include "engine/sblr/sblr_versioned_tag_runtime.hpp"
#include "core/hash/hash_digest.hpp"
#include <algorithm>
#include <cstring>
namespace scratchbird::engine::sblr{namespace{void put(std::vector<std::uint8_t>&o,std::uint64_t v,int n){for(int i=0;i<n;i++)o.push_back(v>>(8*i));}std::uint32_t get(const std::uint8_t*p){return p[0]|p[1]<<8|p[2]<<16|p[3]<<24;}bool nz(const auto&a){return std::any_of(a.begin(),a.end(),[](auto x){return x!=0;});}std::array<std::uint8_t,32> h(const std::uint8_t*p){std::vector<std::uint8_t>x={'S','B','O','D','|','S','B','D','D','|','v','1'};x.insert(x.end(),p,p+352);return core::hash::ComputeSha256Digest(x).digest;}}
std::vector<std::uint8_t>EncodeSblrVersionedTagRequestV1(const SblrVersionedTagRequestV1&v){if(!nz(v.operation)||!nz(v.receipt)||v.descriptor_length!=384)return{};std::vector<std::uint8_t>o={'S','B','D','Q'};put(o,1,2);put(o,8,2);put(o,7627,4);put(o,614,4);o.insert(o.end(),v.operation.begin(),v.operation.end());o.insert(o.end(),v.receipt.begin(),v.receipt.end());put(o,384,4);o.resize(64);return o;}bool DecodeSblrVersionedTagRequestV1(const std::uint8_t*p,std::size_t n,SblrVersionedTagRequestV1*o,std::string*e){if(!o||!p||n!=64||std::memcmp(p,"SBDQ",4)||get(p+8)!=7627||get(p+12)!=614||std::any_of(p+52,p+64,[](auto x){return x;})){if(e)*e="request invalid";return false;}std::copy_n(p+16,16,o->operation.begin());std::copy_n(p+32,16,o->receipt.begin());o->descriptor_length=get(p+48);return nz(o->operation)&&nz(o->receipt)&&o->descriptor_length==384;}std::vector<std::uint8_t>EncodeSblrVersionedTagDescriptorV1(const SblrVersionedTagDescriptorV1&v){if(!nz(v.body))return{};std::vector<std::uint8_t>o={'S','B','D','D',1,0,0,0};o.insert(o.end(),v.body.begin(),v.body.end());auto z=h(o.data());std::copy(z.begin(),z.end(),o.begin()+352);return o;}bool DecodeSblrVersionedTagDescriptorV1(const std::uint8_t*p,std::size_t n,SblrVersionedTagDescriptorV1*o,std::string*e){if(!o||!p||n!=384||std::memcmp(p,"SBDD",4)||!std::equal(h(p).begin(),h(p).end(),p+352)){if(e)*e="descriptor invalid";return false;}std::copy_n(p+8,376,o->body.begin());return true;}}
